namespace functioncalls.graph.view;

using functioncalls.graph;
using functioncalls.plugin;
using ghidra.graph.viewer;
using ghidra.graph.viewer;
using ghidra.graph.viewer.options;

/**
 * A graph view for the {@link FunctionCallGraphPlugin}
 */
public class FcgView : VisualGraphView<FcgVertex, FcgEdge, FunctionCallGraph> {

	private VisualGraphOptions options;

	public FcgView(VisualGraphOptions options) {
		this.options = options;
	}

	/* @Override */
	protected void installGraphViewer() {
		FcgComponent component = createGraphComponent();
		component.setGraphOptions(options);

		string viewName = "Function Call Graph";
		GraphViewer<FcgVertex, FcgEdge> viewer = component.getPrimaryViewer();
		viewer.setName(viewName);
		viewer.getAccessibleContext().setAccessibleName(viewName);

		setGraphComponent(component);
	}

	private FcgComponent createGraphComponent() {
		FcgComponent component = new FcgComponent(getVisualGraph());
		return component;
	}

	/* @Override */
	public FcgComponent getGraphComponent() {
		return (FcgComponent) base.getGraphComponent();
	}
}
